{
  "state": "const state = { tasks: store.tasks, selectedDate: dateKey(new Date()), error: store.error, isEditing: false };",
  "binding": "const pageError = document.getElementById('page-error');
const editButton = document.getElementById('edit-tasks');",
  "updateUI": "function updateUI() {
  state.tasks = store.tasks;
  state.error = store.error;
  const hasTasks = state.tasks.some(t => t.date === state.selectedDate);
  if (!hasTasks) state.isEditing = false;
  editButton.disabled = !hasTasks;
  editButton.textContent = state.isEditing ? '완료' : '편집';
  editButton.setAttribute('aria-pressed', String(state.isEditing));
  editButton.setAttribute('aria-label', state.isEditing ? '목록 편집 완료' : '할 일 목록 편집');
  renderPlanner(state);
  if (pageError) pageError.textContent = store.error || '';
}",
  "day": "  state.isEditing = false;
  state.selectedDate = btn.dataset.date;",
  "open": "  lastFocused = document.activeElement;
  state.isEditing = false;
  updateUI();",
  "listener": "editButton.addEventListener('click', () => {
  state.isEditing = !state.isEditing;
  updateUI();
  editButton.focus();
});
updateUI();"
